mapper.update:
UPDATE ws_project
project_name = #{project_name}, project_type = #{project_type}, status = #{status}, current_version = #{current_version}, snapshots = #{snapshots}, edit_history = #{edit_history}, permissions = #{permissions}, deleted_at = #{deleted_at}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT  FROM ws_project

    deleted_at IS NULL
    AND user_id = #{user_id}
    AND project_type = #{project_type}
    AND status = #{status}
    AND project_name LIKE CONCAT('%', #{keyword}, '%')

ORDER BY updated_at DESC
